    fun all(): List<Deck> = sources.mapIndexed { rank, source ->
        val deckId = stableId(source.title)
        val sourceModifiers = if (source.expand) modifiers else listOf("original")
        val cards = source.base.flatMapIndexed { baseIndex, phrase ->
            sourceModifiers.mapIndexed { modifierIndex, modifier ->
                val text = if (modifierIndex == 0) phrase else "$phrase: $modifier"
                Prompt(stableId("$deckId:$text"), text, Difficulty.entries[(baseIndex + modifierIndex) % 3], source.description)
            }
        }
        Deck(deckId, source.title, source.description, 1, "2026-01-01T00:00:00Z", cards.size,
            ageRestricted = source.restricted, featuredRank = if (rank < 4) rank + 1 else null, cards = cards)
    }

    private fun stableId(value: String): String = UUID.nameUUIDFromBytes(value.toByteArray(StandardCharsets.UTF_8)).toString()
}

